// Dynamic Gmail Payload Parser (Extracts real Sender Name, Email, Subject & Snippet)
return $input.all().map((item) => {
  const j = item.json || {};
  const rawFrom = String(j.from || j.From || (j.headers && j.headers.from) || 'Sarah Jenkins <sarah@apexconsulting.io>');
  const emailMatch = rawFrom.match(/<([^>]+)>/);
  const senderEmail = emailMatch ? emailMatch[1].trim() : (rawFrom.includes('@') ? rawFrom.trim() : 'sarah@apexconsulting.io');
  const senderName = rawFrom.split('<')[0].replace(/"/g, '').trim() || senderEmail.split('@')[0];

  const subject = j.subject || j.Subject || (j.headers && j.headers.subject) || 'New Monthly Retainer Agreement & Onboarding PDF';
  const snippet = String(j.snippet || j.textPlain || 'Hi team, attached is our signed monthly retainer agreement and project kickoff schedule.').replace(/\s+/g, ' ').slice(0, 220);
  const rawDate = j.date || j.Date || new Date().toISOString();

  return {
    json: {
      Received_Date: String(rawDate).slice(0, 16).replace('T', ' '),
      Sender_Name: senderName,
      Sender_Email: senderEmail,
      Email_Subject: subject,
      Summary_Snippet: snippet,
      Status: '✓ Synced via Self-Hosted n8n Bridge ($0 Fees)'
    }
  };
});
